using System.Text.Json;
using Clary.Api.Identity;
using NpgsqlTypes;
namespace Clary.Api;
public record TicketTemplateInput(string Name,string Type,string Instructions,string AssignmentMode="Users",IReadOnlyList<Guid>? AssigneeIds=null,IReadOnlyList<Guid>? DocumentIds=null,Guid? KitId=null,IReadOnlyList<string>? Checklist=null,int? Revision=null);
public record TicketTemplate(Guid Id,string Name,string Type,string Instructions,string AssignmentMode,IReadOnlyList<Guid> AssigneeIds,IReadOnlyList<Guid> DocumentIds,Guid? KitId,IReadOnlyList<string> Checklist,int Revision);
public record TicketChecklistItem(Guid Id,string Text,bool Completed=false,string? CompletedBy=null,DateTime? CompletedAt=null);
public record TicketChecklistInput(bool Completed,int Revision);
public sealed partial class TicketRepository {
 internal static IReadOnlyList<string> ChecklistText(IReadOnlyList<string>? values){var items=(values??[]).Select(v=>Text(v,300,true)).ToArray();if(items.Length>50||items.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=items.Length)throw new ArgumentException("Use up to 50 distinct checklist items.");return items;}
 public async Task<IReadOnlyList<TicketTemplate>> TemplatesAsync(CompanyContext c,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(!TicketAccess.Manager(c))throw new CompanyDenied();
  await using var q=Q(conn,tx,c,"SELECT id,name,type,instructions,assignment_mode,assignee_ids::text,document_ids::text,kit_id,checklist::text,revision FROM ticket_templates WHERE company_id=@company ORDER BY name,id");var items=new List<TicketTemplate>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))items.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),JsonSerializer.Deserialize<Guid[]>(r.GetString(5),Json)!,JsonSerializer.Deserialize<Guid[]>(r.GetString(6),Json)!,r.IsDBNull(7)?null:r.GetGuid(7),JsonSerializer.Deserialize<string[]>(r.GetString(8),Json)!,r.GetInt32(9)));return items;
 }
 public async Task<TicketTemplate> SaveTemplateAsync(CompanyContext c,Guid? id,TicketTemplateInput input,CancellationToken ct){
  var name=Text(input.Name,100,true);var instructions=Text(input.Instructions,8000);var checklist=ChecklistText(input.Checklist);var users=(input.AssigneeIds??[]).Distinct().ToArray();var docs=(input.DocumentIds??[]).Distinct().ToArray();
  if(!new[]{"Support","Equipment","Onboarding","Repair","Retirement"}.Contains(input.Type)||input.AssignmentMode is not ("Users" or "All")||users.Length>100||docs.Length>30)throw new ArgumentException("Choose valid template parameters.");
  if(input.KitId is not null&&input.Type is not ("Equipment" or "Onboarding"))throw new ArgumentException("Equipment kits apply to equipment or onboarding templates.");
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);if(!AccountPermissions.Allows(c,CompanyCapability.Settings))throw new CompanyDenied();
  foreach(var doc in docs)await Exists(conn,tx,c,"documents",doc,ct);await Exists(conn,tx,c,"equipment_kits",input.KitId,ct);
  foreach(var user in users){await using var check=Q(conn,tx,c,"SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.company_id=@company AND m.user_id=@assigned AND m.active AND u.active");check.Parameters.AddWithValue("assigned",user);if(await check.ExecuteScalarAsync(ct) is null)throw new ArgumentException("Choose active company users.");}
  var key=id??Guid.NewGuid();int revision=1;
  await using(var duplicate=Q(conn,tx,c,"SELECT 1 FROM ticket_templates WHERE company_id=@company AND lower(btrim(name))=lower(@name) AND id<>@id")){duplicate.Parameters.AddWithValue("name",name);duplicate.Parameters.AddWithValue("id",key);if(await duplicate.ExecuteScalarAsync(ct) is not null)throw new InventoryConflict("A ticket template with this name already exists. Choose another name.");}
  if(id is not null){await using var check=Q(conn,tx,c,"SELECT revision FROM ticket_templates WHERE company_id=@company AND id=@id FOR UPDATE");check.Parameters.AddWithValue("id",key);var value=await check.ExecuteScalarAsync(ct);if(value is null)throw new InventoryMissing();if((int)value!=input.Revision)throw new InventoryConflict("Template changed. Reload before saving.");revision=(int)value+1;}
  var result=new TicketTemplate(key,name,input.Type,instructions,input.AssignmentMode,users,docs,input.KitId,checklist,revision);
  await using(var q=Q(conn,tx,c,id is null?"INSERT INTO ticket_templates(company_id,id,name,type,instructions,assignment_mode,assignee_ids,document_ids,kit_id,checklist) VALUES(@company,@id,@name,@type,@instructions,@mode,@users,@docs,@kit,@checklist)":"UPDATE ticket_templates SET name=@name,type=@type,instructions=@instructions,assignment_mode=@mode,assignee_ids=@users,document_ids=@docs,kit_id=@kit,checklist=@checklist,revision=revision+1 WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",key);q.Parameters.AddWithValue("name",name);q.Parameters.AddWithValue("type",input.Type);q.Parameters.AddWithValue("instructions",instructions);q.Parameters.AddWithValue("mode",input.AssignmentMode);q.Parameters.AddWithValue("users",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(users,Json));q.Parameters.AddWithValue("docs",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(docs,Json));P(q,"kit",input.KitId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("checklist",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(checklist,Json));await q.ExecuteNonQueryAsync(ct);}
  await AuditRepository.AppendAsync(conn,tx,c,id is null?"Created":"Updated","ticket-template",key,null,result,ct);await tx.CommitAsync(ct);return result;
 }
 public async Task<TicketDto> CheckAsync(CompanyContext c,Guid id,Guid item,TicketChecklistInput input,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);c=await TicketAccess.LiveAsync(conn,tx,c,ct);await Lock(conn,tx,c,id,ct);var before=await Get(conn,tx,c,id,ct)??throw new InventoryMissing();
  if(!TicketAccess.Assigned(before,c)&&!TicketAccess.Administrator(c))throw new CompanyDenied();if(before.Revision!=input.Revision||before.Status is "Complete" or "Canceled")throw new InventoryConflict("Ticket changed or closed. Refresh before updating its checklist.");if(!before.Checklist.Any(x=>x.Id==item))throw new InventoryMissing();
  var actor=await Actor(conn,tx,c,ct);var items=before.Checklist.Select(x=>x.Id==item?x with{Completed=input.Completed,CompletedBy=input.Completed?actor:null,CompletedAt=input.Completed?DateTime.UtcNow:null}:x).ToArray();
  await using(var q=Q(conn,tx,c,"UPDATE equipment_tickets SET checklist=@items,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id")){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("items",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(items,Json));await q.ExecuteNonQueryAsync(ct);}
  await Activity(conn,tx,c,id,input.Completed?"Checklist completed":"Checklist reopened",before.Checklist.First(x=>x.Id==item).Text,ct);var after=(await Get(conn,tx,c,id,ct))!;await AuditRepository.AppendAsync(conn,tx,c,"Checklist updated","equipment-ticket",id,before,after,ct);await tx.CommitAsync(ct);return after;
 }
}
